package org.transittr;
import android.content.Context;import java.util.*;import org.json.*;
/** A small, bounded, local-only history of submitted stop and line searches. */
public final class RecentQueries {
 public static final class Entry {public int city;public String stop,line,direction;}
 public static JSONArray update(String previous,int city,String stop,String line,String direction)throws JSONException{JSONArray old;try{old=new JSONArray(previous);}catch(JSONException bad){old=new JSONArray();}JSONArray result=new JSONArray();JSONObject fresh=new JSONObject();fresh.put("city",city);fresh.put("stop",stop);fresh.put("line",line);fresh.put("direction",direction);result.put(fresh);for(int i=0;i<old.length()&&result.length()<8;i++){JSONObject row=old.optJSONObject(i);if(row==null)continue;if(row.optInt("city",-1)==city&&stop.equals(row.optString("stop"))&&line.equalsIgnoreCase(row.optString("line"))&&direction.equals(row.optString("direction")))continue;result.put(row);}return result;}
 public static void record(Context c,int city,String stop,String line,String direction){try{android.content.SharedPreferences p=c.getSharedPreferences("recent-queries-v1",0);p.edit().putString("items",update(p.getString("items","[]"),city,stop,line,direction).toString()).commit();}catch(JSONException ignored){}}
 public static ArrayList<Entry> all(Context c){ArrayList<Entry> out=new ArrayList<Entry>();try{JSONArray a=new JSONArray(c.getSharedPreferences("recent-queries-v1",0).getString("items","[]"));for(int i=0;i<a.length()&&i<8;i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;Entry e=new Entry();e.city=o.optInt("city",-1);e.stop=o.optString("stop","");e.line=o.optString("line","");e.direction=o.optString("direction","");if(CityRegistry.valid(e.city)&&e.stop.matches(e.city==0?"[0-9]{5}":"[0-9]{1,8}")&&e.line.matches("[A-Za-z0-9ÇĞİÖŞÜçğıöşü-]{0,16}")&&(e.direction.equals("")||e.city==1&&(e.direction.equals("G")||e.direction.equals("D"))))out.add(e);}}catch(JSONException ignored){}return out;}
}
